OPTION_TEXT = {'q001': {'MAIN identifies four immediate diplomatic decisions; the assassination explains why the blocs already existed.': 'MAIN describes four decisions made during the crisis; the assassination explains why the alliances already existed.', 'MAIN describes long-term pressures; the assassination triggered a particular crisis.': 'MAIN describes long-term tensions; the assassination triggered the immediate crisis.', 'MAIN describes the underlying tensions, but the assassination was a consequence of the declarations of war.': 'MAIN describes long-term tensions, but the assassination happened after countries declared war.', 'MAIN explains why the first battles became stalemates; the assassination explains the long-term rivalries.': 'MAIN explains why battles became stalemates; the assassination explains the long-term rivalries.'}, 'q044': {'Restoring color to archival footage turns it into the same kind of source as a fictional reenactment.': 'Adding color to old footage makes it the same kind of source as a fictional reenactment.', 'Archival footage gives an unselected record, so its editing and context are less important than a drama’s.': 'Footage from the war shows everything without selection, so historians can ignore how it was edited.', 'A modern dramatic film provides direct eyewitness testimony if its setting is historically accurate.': 'A modern dramatic film is an eyewitness account if it gets the historical setting right.', 'A film’s emotional impact is enough to establish how typical its portrayed experience was.': 'A film’s emotional impact proves that most soldiers had the experience it shows.', 'A dramatic film can interpret war, while archival material is evidence that still requires context.': 'A dramatic film interprets the war; footage from the war records evidence that still needs context.'}, 'q067': {'Formal neutrality coexisted with growing economic ties to Britain and France.': 'The United States stayed officially neutral while its trade ties with Britain and France grew.', 'Economic ties remained approximately balanced despite increasing political tension.': 'American trade with the two sides stayed roughly balanced as political tensions increased.', 'American trade shifted toward the Central Powers as the Allied blockade weakened.': 'American trade shifted toward the Central Powers as the Allied blockade weakened.', 'Britain’s exports to the United States grew while American exports to France declined.': 'British exports to the United States grew while American exports to France fell.', 'The United States traded mainly with Germany until immediately before its declaration of war.': 'The United States traded mainly with Germany until just before entering the war.', 'The chart measures government loans rather than the value of goods exported.': 'The chart shows government loans, not the value of goods sold abroad.'}, 'q069': {'It reports Japan’s formal decision to leave the Allies and mediate a German-American peace.': 'Japan had formally agreed to leave the Allies and help negotiate peace between Germany and America.', 'It proposed an alliance and territorial support; it does not prove Mexico accepted.': 'Germany offered Mexico an alliance and help recovering territory; the message does not prove Mexico accepted.', 'It records an alliance Mexico had accepted and Germany was now putting into effect.': 'Mexico had already accepted the alliance, and Germany was putting it into action.', 'It describes territorial concessions the United States had already agreed to in peace talks.': 'The United States had already agreed in peace talks to give up territory.'}, 'q080': {'The peace conference treated cultural and political boundaries as identical throughout Europe.': 'The conference assumed political borders already matched cultural boundaries everywhere in Europe.', 'National populations overlapped, while the victors also pursued security, territory, and imperial interests.': 'Different national groups lived in the same areas, and the victors also wanted security, territory, and control of colonies.', 'Allied governments applied national independence mainly to their own overseas possessions.': 'The Allies gave independence mainly to people in their own overseas colonies.', 'Most disputed areas contained a single national community whose claims did not overlap.': 'Most disputed areas contained only one national group, so claims rarely overlapped.'}, 'q084': {'The Senate did not give the consent required for U.S. ratification.': 'The U.S. Senate did not give the approval needed for the United States to accept the treaty.', 'The treaty required a national referendum that Wilson declined to hold.': 'The treaty required a national public vote that Wilson refused to hold.', 'The House of Representatives alone had to consent, and the Senate approved without reservations.': 'Only the House of Representatives had to approve it, and the Senate supported it without objections.', 'The League’s members had to ratify American membership before the Senate could consider the treaty.': 'League members had to approve American membership before the Senate could consider the treaty.'}}
def apply_wording(questions):
    for q in questions:
        if q['id'] in STEMS:q['stem']=STEMS[q['id']]
        if q['id'] in OPTION_TEXT:q['options']=[OPTION_TEXT[q['id']].get(option,option) for option in q['options']]
    return questions
